  function renderInsightsChart(){if(state.view!=='\x69\x6e\x73\x69\x67\x68\x74\x73'||!$('\x69\x6e\x73\x69\x67\x68\x74\x54\x72\x65\x6e\x64\x43\x68\x61\x72\x74'))return;const rows=selectedMonthSessions(),d=engine.dashboard();if(state.insightsTab==='\x72\x65\x63\x6f\x76\x65\x72\x79'){d.monthly.length?drawLines($('\x69\x6e\x73\x69\x67\x68\x74\x54\x72\x65\x6e\x64\x43\x68\x61\x72\x74'),d.monthly.map(x=>x.monthLabel),[{label:'\x52\x65\x61\x64\x69\x6e\x65\x73\x73',values:d.monthly.map(x=>x.readinessScore*100),color:'\x23\x31\x63\x62\x37\x63\x39'}],{suffix:'\x25',min:0,max:100}):drawEmptyChart($('\x69\x6e\x73\x69\x67\x68\x74\x54\x72\x65\x6e\x64\x43\x68\x61\x72\x74'),'\x57\x61\x69\x74\x69\x6e\x67 \x66\x6f\x72 \x6c\x69\x76\x65 \x72\x65\x63\x6f\x76\x65\x72\x79 \x64\x61\x74\x61');return;}const series=dailySessionSeries(rows,state.insightsTab==='\x65\x6e\x67\x61\x67\x65\x6d\x65\x6e\x74'?'\x68\x6f\x75\x72\x73':'\x63\x6f\x6d\x70\x6c\x65\x74\x69\x6f\x6e');series.length?drawLines($('\x69\x6e\x73\x69\x67\x68\x74\x54\x72\x65\x6e\x64\x43\x68\x61\x72\x74'),series.map(x=>x.label),[{label:state.insightsTab==='\x65\x6e\x67\x61\x67\x65\x6d\x65\x6e\x74'?'\x48\x6f\x75\x72\x73':'\x43\x6f\x6d\x70\x6c\x65\x74\x69\x6f\x6e',values:series.map(x=>x.value),color:'\x23\x31\x63\x62\x37\x63\x39'}],state.insightsTab==='\x65\x6e\x67\x61\x67\x65\x6d\x65\x6e\x74'?{}:{suffix:'\x25',min:0,max:100}):drawEmptyChart($('\x69\x6e\x73\x69\x67\x68\x74\x54\x72\x65\x6e\x64\x43\x68\x61\x72\x74'),'\x57\x61\x69\x74\x69\x6e\x67 \x66\x6f\x72 \x6c\x69\x76\x65 \x77\x6f\x72\x6b \x64\x61\x74\x61');}

