    const body=rows.length?rows.map(e=>{const rate=hourlyRateFor(e.employeeId,'');return `<tr><td><b>${esc(e.employeeId)}</b></td><td>${userIdentity(e,'',e.position||e.employeeId,'\x78\x73')}</td><td>${esc(e.position||'\u2014')}</td><td>${esc(e.department||'\u2014')}</td><td>${esc(e.employmentType||'\x46\x75\x6c\x6c \x54\x69\x6d\x65')}</td><td>${directoryStatusChip(employmentStatus(e))}</td><td>${esc(e.location||'\u2014')}</td><td><span class="directory-contact">${esc(e.email||e.phone||'\u2014')}</span></td><td class="num">${rate?money(rate,activeCurrency(),2):'\u2014'}</td><td class="directory-actions">•••</td></tr>`;}).join(''):'\x3c\x74\x72 \x63\x6c\x61\x73\x73\x3d"\x65\x6d\x70\x74\x79\x2d\x72\x6f\x77"\x3e\x3c\x74\x64 \x63\x6f\x6c\x73\x70\x61\x6e\x3d"\x31\x30"\x3e\x3c\x64\x69\x76 \x63\x6c\x61\x73\x73\x3d"\x74\x61\x62\x6c\x65\x2d\x65\x6d\x70\x74\x79"\x3e\x3c\x62\x3e\x4e\x6f \x6c\x69\x76\x65 \x65\x6d\x70\x6c\x6f\x79\x65\x65\x73 \x79\x65\x74\x3c\x2f\x62\x3e\x3c\x73\x70\x61\x6e\x3e\x41\x64\x64 \x61\x6e \x65\x6d\x70\x6c\x6f\x79\x65\x65, \x63\x6f\x6d\x70\x6c\x65\x74\x65 \x6f\x6e\x62\x6f\x61\x72\x64\x69\x6e\x67, \x6f\x72 \x62\x65\x67\x69\x6e \x61 \x57\x6f\x72\x6b \x41\x63\x74\x69\x76\x69\x74\x79 \x48\x75\x62 \x73\x65\x73\x73\x69\x6f\x6e \x74\x6f \x65\x73\x74\x61\x62\x6c\x69\x73\x68 \x74\x68\x65 \x6c\x69\x76\x65 \x64\x69\x72\x65\x63\x74\x6f\x72\x79\x2e\x3c\x2f\x73\x70\x61\x6e\x3e\x3c\x2f\x64\x69\x76\x3e\x3c\x2f\x74\x64\x3e\x3c\x2f\x74\x72\x3e';
    $('\x65\x6d\x70\x6c\x6f\x79\x65\x65\x73\x54\x61\x62\x6c\x65').innerHTML=`<thead><tr><th>ID#</th><th>Full Name</th><th>Position</th><th>Department</th><th>Type</th><th>Status</th><th>Location</th><th>Contacts</th><th>Hourly rate</th><th></th></tr></thead><tbody>${body}</tbody>`;
