    const keys=['\x65\x76\x69\x64\x65\x6e\x63\x65','\x63\x61\x70\x61\x63\x69\x74\x79','\x65\x6c\x69\x67\x69\x62\x69\x6c\x69\x74\x79','\x62\x75\x64\x67\x65\x74','\x61\x70\x70\x72\x6f\x76\x61\x6c'];
