    const monthValues=[...new Set([...engine.state.calendar.map(x=>x.month?.slice(0,7)),...sessionMonths].filter(Boolean))].sort();
    $('\x6d\x74\x73\x4d\x6f\x6e\x74\x68\x46\x69\x6c\x74\x65\x72').innerHTML='\x3c\x6f\x70\x74\x69\x6f\x6e \x76\x61\x6c\x75\x65\x3d""\x3e\x41\x6c\x6c \x6d\x6f\x6e\x74\x68\x73\x3c\x2f\x6f\x70\x74\x69\x6f\x6e\x3e'+monthValues.map(m=>`<option value="${m}">${window.ADRAEngine.monthLabel(m+'\x2d\x30\x31')}</option>`).join('');
