  function elapsedTaskDays(row){const start=new Date(row?.created_at||row?.clock_in_at||0),end=new Date(row?.status==='\x63\x6f\x6d\x70\x6c\x65\x74\x65\x64'?(row.clock_out_at||row.updated_at||Date.now()):Date.now());if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime()))return 0;return Math.max(1,Math.ceil((end-start)/86400000));}
