  async function clearAgentConversation(startNew=false){try{if(STANDALONE_MODE){await supabaseRpc('\x61\x73\x73\x75\x72\x61\x6e\x63\x65\x5f\x72\x65\x67\x65\x6e\x74\x5f\x62\x72\x6f\x77\x73\x65\x72\x5f\x61\x67\x65\x6e\x74\x5f\x63\x6c\x65\x61\x72',{p_token:browserSessionToken});}else{const r=await apiFetch(`/api/brain/thread?actor_id=${encodeURIComponent(controlActorId())}&start_new=${startNew?'\x74\x72\x75\x65':'\x66\x61\x6c\x73\x65'}`,{method:'\x44\x45\x4c\x45\x54\x45'});if(!r.ok){const b=await r.json().catch(()=>({}));throw new Error(b.error||'\x43\x6f\x75\x6c\x64 \x6e\x6f\x74 \x63\x6c\x65\x61\x72 \x63\x6f\x6e\x76\x65\x72\x73\x61\x74\x69\x6f\x6e\x2e');}}$('\x63\x68\x61\x74\x4d\x65\x73\x73\x61\x67\x65\x73').innerHTML='\x3c\x64\x69\x76 \x63\x6c\x61\x73\x73\x3d"\x61\x67\x65\x6e\x74\x2d\x65\x6d\x70\x74\x79" \x69\x64\x3d"\x61\x67\x65\x6e\x74\x45\x6d\x70\x74\x79\x53\x74\x61\x74\x65"\x3e\x3c\x2f\x64\x69\x76\x3e';hidePredictiveCompose();pendingApproval=null;if($('\x61\x70\x70\x72\x6f\x76\x61\x6c\x44\x69\x61\x6c\x6f\x67')?.open)$('\x61\x70\x70\x72\x6f\x76\x61\x6c\x44\x69\x61\x6c\x6f\x67').close();window.dispatchEvent(new CustomEvent('\x61\x73\x73\x75\x72\x61\x6e\x63\x65\x2d\x72\x65\x67\x65\x6e\x74\x2d\x61\x67\x65\x6e\x74\x2d\x74\x68\x72\x65\x61\x64\x2d\x72\x65\x73\x65\x74',{detail:{reason:startNew?'\x6e\x65\x77':'\x63\x6c\x65\x61\x72'}}));toast(startNew?'\x4e\x65\x77 \x52\x65\x63\x6f\x76\x65\x72\x79 \x41\x67\x65\x6e\x74 \x63\x6f\x6e\x76\x65\x72\x73\x61\x74\x69\x6f\x6e \x73\x74\x61\x72\x74\x65\x64\x2e':'\x52\x65\x63\x6f\x76\x65\x72\x79 \x41\x67\x65\x6e\x74 \x63\x6f\x6e\x76\x65\x72\x73\x61\x74\x69\x6f\x6e \x63\x6c\x65\x61\x72\x65\x64\x2e');await refreshControlCenter();return true;}catch(err){toast(err.message);throw err;}}

  function exportData(kind){let rows=[];if(kind==='\x6d\x6f\x6e\x74\x68\x6c\x79'||kind==='\x65\x6e\x67\x69\x6e\x65')rows=engine.monthlyEngine();if(kind==='\x70\x72\x6f\x6a\x65\x63\x74\x73')rows=engine.state.projects;if(kind==='\x65\x6d\x70\x6c\x6f\x79\x65\x65\x73')rows=engine.state.employees;if(kind==='\x76\x61\x63\x61\x6e\x63\x69\x65\x73')rows=engine.state.vacancies;if(kind==='\x63\x61\x6e\x64\x69\x64\x61\x74\x65\x73')rows=engine.state.candidates;if(kind==='\x6f\x6e\x62\x6f\x61\x72\x64\x69\x6e\x67')rows=engine.state.onboarding;if(!rows.length)return toast('\x4e\x6f \x6c\x69\x76\x65 \x72\x65\x63\x6f\x72\x64\x73 \x61\x72\x65 \x61\x76\x61\x69\x6c\x61\x62\x6c\x65 \x74\x6f \x65\x78\x70\x6f\x72\x74\x2e');const headers=Object.keys(rows[0]);const csv=[headers.join(','),...rows.map(r=>headers.map(h=>`"${String(r[h]??'').replaceAll('"','""')}"`).join(','))].join('\n');const blob=new Blob([csv],{type:'\x74\x65\x78\x74\x2f\x63\x73\x76'}),a=document.createElement('\x61');a.href=URL.createObjectURL(blob);a.download=`adra-${kind}.csv`;a.click();URL.revokeObjectURL(a.href);}
