  function prepCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(500,rect.width*dpr);canvas.height=280*dpr;const c=canvas.getContext('\x32\x64');c.setTransform(dpr,0,0,dpr,0,0);return {c,w:canvas.width/dpr,h:280};}
