  function axes(c,w,h,pad,min,max,labels,suffix=''){c.clearRect(0,0,w,h);c.strokeStyle='\x23\x65\x33\x65\x63\x65\x66';c.fillStyle='\x23\x37\x38\x39\x30\x39\x62';c.lineWidth=1;c.font='\x39\x70\x78 \x73\x79\x73\x74\x65\x6d\x2d\x75\x69';for(let i=0;i<=4;i++){const y=pad.t+(h-pad.t-pad.b)*(i/4);c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();const v=max-(max-min)*(i/4);c.fillText(`${compact(v)}${suffix}`,4,y+3);}labels.forEach((x,i)=>{const cx=pad.l+(w-pad.l-pad.r)*(labels.length===1?.5:i/(labels.length-1||1));c.fillText(x,cx-16,h-8);});}
  function compact(v){const a=Math.abs(v);if(a>=1e6)return `${(v/1e6).toFixed(1)}m`;if(a>=1e3)return `${(v/1e3).toFixed(0)}k`;return `${Math.round(v)}`;}
  function drawLines(canvas,labels,series,opt={}){if(!canvas)return;const {c,w,h}=prepCanvas(canvas),pad={l:45,r:14,t:28,b:30};let vals=series.flatMap(s=>s.values).filter(Number.isFinite),min=opt.min??Math.min(0,...vals),max=opt.max??Math.max(...vals);if(max===min)max=min+1;axes(c,w,h,pad,min,max,labels,opt.suffix||'');series.forEach(s=>{c.strokeStyle=s.color;c.fillStyle=s.color;c.lineWidth=2.3;c.beginPath();s.values.forEach((v,i)=>{const x=pad.l+(w-pad.l-pad.r)*(i/(labels.length-1||1)),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();s.values.forEach((v,i)=>{const x=pad.l+(w-pad.l-pad.r)*(i/(labels.length-1||1)),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b);c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.fill();});});drawLegend(c,series,w);}
  function drawGroupedBars(canvas,labels,series,opt={}){if(!canvas)return;const vals=series.flatMap(s=>s.values).filter(Number.isFinite);if(!labels.length||!vals.length)return drawEmptyChart(canvas,'\x57\x61\x69\x74\x69\x6e\x67 \x66\x6f\x72 \x6c\x69\x76\x65 \x64\x61\x74\x61');const {c,w,h}=prepCanvas(canvas),pad={l:50,r:14,t:32,b:32};let min=Math.min(0,...vals),max=Math.max(...vals);if(max===min)max=min+1;axes(c,w,h,pad,min,max,labels);const area=w-pad.l-pad.r,group=area/labels.length,bw=Math.max(3,Math.min(18,(group-12)/series.length));series.forEach((s,si)=>{c.fillStyle=s.color;s.values.forEach((v,i)=>{const zero=pad.t+(max)/(max-min)*(h-pad.t-pad.b),y=pad.t+(max-v)/(max-min)*(h-pad.t-pad.b),x=pad.l+i*group+group/2-(series.length*bw)/2+si*bw;c.fillRect(x,Math.min(y,zero),bw-2,Math.abs(zero-y));});});drawLegend(c,series,w);}
  function drawHorizontalBars(canvas,labels,values,color,opt={}){if(!canvas)return;const hasPeople=Array.isArray(opt.people)&&opt.people.length>0,{c,w,h}=prepCanvas(canvas),pad={l:hasPeople?128:95,r:35,t:24,b:18};c.clearRect(0,0,w,h);const min=Math.min(0,...values),max=Math.max(0,...values),range=(max-min)||1,barH=Math.min(18,(h-pad.t-pad.b)/Math.max(labels.length,1)-5);c.font='\x39\x70\x78 \x73\x79\x73\x74\x65\x6d\x2d\x75\x69';labels.forEach((lab,i)=>{const y=pad.t+i*((h-pad.t-pad.b)/labels.length),person=hasPeople?opt.people[i]:null,photo=safeProfilePhoto(person?.profilePhoto),textX=hasPeople?29:5;c.fillStyle='\x23\x36\x33\x37\x62\x38\x37';c.fillText(lab,textX,y+barH*.75);if(hasPeople){c.save();c.beginPath();c.arc(14,y+barH/2,9,0,Math.PI*2);c.clip();c.fillStyle='\x23\x64\x37\x65\x64\x66\x35';c.fillRect(5,y+barH/2-9,18,18);c.restore();if(photo){const img=new Image();img.onload=()=>{c.save();c.beginPath();c.arc(14,y+barH/2,9,0,Math.PI*2);c.clip();c.drawImage(img,5,y+barH/2-9,18,18);c.restore();};img.src=photo;}else{c.fillStyle='\x23\x33\x38\x35\x64\x36\x64';c.font='\x62\x6f\x6c\x64 \x36\x70\x78 \x73\x79\x73\x74\x65\x6d\x2d\x75\x69';c.textAlign='\x63\x65\x6e\x74\x65\x72';c.fillText(companyInitials(lab),14,y+barH/2+2);c.textAlign='\x73\x74\x61\x72\x74';c.font='\x39\x70\x78 \x73\x79\x73\x74\x65\x6d\x2d\x75\x69';}}const zero=pad.l+(-min/range)*(w-pad.l-pad.r),x=pad.l+((values[i]-min)/range)*(w-pad.l-pad.r);c.strokeStyle='\x23\x65\x34\x65\x63\x65\x66';c.beginPath();c.moveTo(pad.l,y+barH+4);c.lineTo(w-pad.r,y+barH+4);c.stroke();c.fillStyle=color;c.fillRect(Math.min(zero,x),y,Math.max(2,Math.abs(x-zero)),barH);c.fillStyle='\x23\x34\x32\x35\x62\x36\x37';c.fillText(num(values[i],1),Math.min(w-pad.r-25,Math.max(zero,x)+5),y+barH*.75);});}
